#!/usr/bin/env python3
"""mknotes: regenerate engine/notes.inc (note half-periods for sound.asm).
Public domain (Unlicense)."""
import os
names = ['C', 'CS', 'D', 'DS', 'E', 'F', 'FS', 'G', 'GS', 'A', 'AS', 'B']
out = ["; notes.inc: musical notes as speaker half-periods for the sound engine",
       "; (HALF = 447443 / frequency; equal temperament, A4 = 440 Hz).  Use them",
       "; in effect segments: fcb FRAMES, SND_TONE / fdb N_C5, 0.  The range is",
       "; kept where the interrupt cost is modest (C4 ~7%, C6 ~25% of the CPU).",
       "; Generated by tools/mknotes.py."]
for octave in (3, 4, 5, 6):
    for i, n in enumerate(names):
        if octave == 6 and i > 4: break
        midi = 12 * (octave + 1) + i
        f = 440 * 2 ** ((midi - 69) / 12)
        out.append(f"N_{n}{octave:<2}{'':6}equ     {round(447443 / f):5}   ; {f:7.1f} Hz")
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'engine', 'notes.inc'), 'w').write("\n".join(out) + "\n")
